entries[2881] = { ["name"] = "Pläne: Runenverzierte Kupferbrustplatte", ["text"] = "Benötigt Schmiedekunst (80)\nBenutzen: Lehrt Euch die Herstellung einer runenverzierten Kupferbrustplatte.\nVerkaufspreis:\nRunenverzierte Kupferbrustplatte\nWird beim Anlegen gebunden\nBrust Kette\n131 Rüstung\n+4 Stärke\n+3 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 13\nVerkaufspreis:\nBenötigt Kupferbarren (12), Schattenedelstein , Rauer Schleifstein (2)" }
