entries[3089] = { ["name"] = "Foliant des Flammenstoßes", ["text"] = "Klassen: Magier\nBenötigt Stufe 16\nBenutzen: Lehrt 'Flammenstoß' (Rang 1).\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 27 Feuerschaden und zusätzlich im Verlauf von 8 Sek. 48 Feuerschaden zufügt.\nVerkaufspreis:" }
