entries[3096] = { ["name"] = "Foliant des Federfalls", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Federfall'.\nVerlangsamt 30 Sek. lang das Falltempo eines befreundeten Gruppen- oder Schlachtzugsmitglieds.\nVerkaufspreis:" }
entries[3097] = { ["name"] = "Foliant des Wasserherbeizauberns II", ["text"] = "Klassen: Magier\nBenötigt Stufe 10\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 2).\nZaubert 20 Flaschen frisches Wasser herbei, die den Magier sowie seine Verbündeten mit etwas Trinkbarem versorgen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes Frischwasser\nHerbeigezauberter Gegenstand\nBenötigt Stufe 5\nBenutzen: Stellt im Verlauf von 21 Sek. insgesamt 437 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
